const D = { density:.5, scale:1, energy:.6, hue:20, speed:1, heat:.6, x:.5, y:.5, style:'thermal', pal:'ironbow', act:'survey', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style, night=style==='nightvision', contour=style==='contour', xray=style==='xray';
const dens=clp(P.density,0,1), en=clp(P.energy,0,1)*(.5+.5*K.intensity), heat=clp(P.heat,0,1);

// ---- thermal ramps (RGB stops 0..255) ----
const RAMPS={
  ironbow:[[2,2,10],[18,16,86],[92,20,132],[196,40,58],[240,120,18],[255,205,70],[255,255,255]],
  arctic:[[3,5,16],[10,32,82],[28,92,150],[120,182,222],[214,238,255],[255,255,255]],
  plasma:[[12,0,32],[74,10,122],[162,22,150],[228,60,92],[250,150,42],[252,240,122]],
  night:[[0,7,0],[0,52,10],[12,132,24],[78,214,58],[196,255,176],[255,255,255]],
  xray:[[248,249,255],[176,188,220],[108,120,162],[58,66,98],[20,24,46],[3,5,14]],
};
let ramp0 = RAMPS[P.pal]||RAMPS.ironbow;
if(night) ramp0=RAMPS.night; else if(xray) ramp0=RAMPS.xray;
// hue rotation of the whole false-color ramp (honors P.hue)
function rgb2hsb(r,g,b){r/=255;g/=255;b/=255;const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn;let h=0;if(d){if(mx===r)h=((g-b)/d)%6;else if(mx===g)h=(b-r)/d+2;else h=(r-g)/d+4;h*=60;if(h<0)h+=360;}return [h, mx?d/mx:0, mx];}
function hsb2rgb(h,s,v){h=((h%360)+360)%360;const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;let r,g,b;const seg=Math.floor(h/60)%6;if(seg===0){r=c;g=x;b=0;}else if(seg===1){r=x;g=c;b=0;}else if(seg===2){r=0;g=c;b=x;}else if(seg===3){r=0;g=x;b=c;}else if(seg===4){r=x;g=0;b=c;}else{r=c;g=0;b=x;}return [(r+m)*255,(g+m)*255,(b+m)*255];}
const hueOff=P.hue-20;
const rkey=P.pal+'|'+style+'|'+Math.round(hueOff/8);
if(S.rkey!==rkey){ S.rkey=rkey; S.ramp = Math.abs(hueOff)<3? ramp0 : ramp0.map(c=>{const hs=rgb2hsb(c[0],c[1],c[2]); return hsb2rgb(hs[0]+hueOff, hs[1], hs[2]);}); }
let ramp = S.ramp;
const levels=Math.max(4,Math.round(5+dens*7));
function shade(v){
  v=clp(v,0,1);
  let edge=0;
  if(contour){ const s=v*levels; edge=Math.abs(s-Math.round(s)); v=Math.round(s)/levels; }
  const n=ramp.length, f=v*(n-1); let i=Math.floor(f); if(i>=n-1)i=n-2; const t=f-i;
  const a=ramp[i], b=ramp[i+1];
  let r=a[0]+(b[0]-a[0])*t, g=a[1]+(b[1]-a[1])*t, bl=a[2]+(b[2]-a[2])*t;
  if(contour && edge<0.055){ r*=0.18; g*=0.18; bl*=0.18; }   // iso-therm lines
  return [r,g,bl];
}

// ---- low-res heat buffer, size-keyed ----
const LS=96;
const GW=Math.max(24,Math.round(LS*W/Math.max(W,Hh)));
const GH=Math.max(24,Math.round(LS*Hh/Math.max(W,Hh)));
if(!S.buf || S.gw!==GW || S.gh!==GH){ if(S.buf)S.buf.remove&&S.buf.remove(); S.buf=createGraphics(GW,GH); S.gw=GW; S.gh=GH; }
const buf=S.buf;

// ---- blobs (heat sources) — seed-deterministic bases, wander in real time ----
const nB=Math.max(2,Math.round(3+dens*9));
if(S.seedUsed!==P.seed || S.nB!==nB){
  S.seedUsed=P.seed; S.nB=nB; S.blob=[];
  for(let i=0;i<nB;i++) S.blob.push({ x0:0.12+0.76*fr(i*3.1+1), y0:0.15+0.70*fr(i*5.7+2),
    rate:0.08+0.22*fr(i*7.3+3), ph:fr(i*9.1)*TAU, amp:0.05+0.10*fr(i*2.2+4),
    rb:0.08+0.10*fr(i*4.4+5), str:0.5+0.5*fr(i*6.6+6) });
}
// act arc — multi-minute dramaturgy
let wanderScale=1, heatArc=1, conv=0;
if(P.act==='pursuit'){ wanderScale=1.7; heatArc=0.85+0.35*Math.sin(K.t*0.06); conv=0.10*(0.5+0.5*Math.sin(K.t*0.04)); }
else if(P.act==='cooldown'){ heatArc=0.35+0.55*(0.5+0.5*Math.sin(K.t*0.028)); wanderScale=0.7; }
const heatE=heat*heatArc;
const panx=(P.x-0.5), pany=(P.y-0.5);
// live blob positions + heat
const asp=W/Hh;
const bl=S.blob.map(b=>{
  const t=K.t*b.rate*(0.5+P.speed*0.6)*wanderScale;
  let bx=b.x0 + b.amp*Math.sin(t+b.ph) + 0.03*Math.sin(K.t*0.11+b.ph*2) + panx;
  let by=b.y0 + b.amp*Math.cos(t*0.8+b.ph*1.3) + pany;
  bx += (0.5-bx)*conv; by += (0.5-by)*conv;   // pursuit converges toward center
  const pulse=0.7 + 0.4*K.swell + A.bass*1.3 + K.pulse*0.35;
  const rb=b.rb*(0.7+P.scale*0.9)*(0.9+0.15*Math.sin(K.t*0.5+b.ph));
  return {bx,by,rb2:rb*rb, str:b.str*pulse*(0.5+heatE)};
});
const horizon=0.56 + 0.05*Math.sin(K.t*0.05) + pany*0.4;
const tide=0.06*Math.sin(K.t*0.09)+0.05*A.rms;

buf.loadPixels();
const px=buf.pixels;
for(let cy=0;cy<GH;cy++){
  const ny=cy/GH;
  let base;
  if(ny>horizon) base=0.26+(ny-horizon)*0.6; else base=0.16-(horizon-ny)*0.20;
  base+=tide;
  for(let cx=0;cx<GW;cx++){
    const nx=cx/GW;
    let v=base + 0.05*Math.sin(nx*TAU*2+K.t*0.2);
    for(let k=0;k<bl.length;k++){ const b=bl[k]; const dx=(nx-b.bx)*asp, dy=ny-b.by; const d2=dx*dx+dy*dy; v += b.str*b.rb2/(b.rb2+d2*1.4); }
    const col=shade(v);
    const idx=(cy*GW+cx)*4;
    px[idx]=col[0]; px[idx+1]=col[1]; px[idx+2]=col[2]; px[idx+3]=255;
  }
}
buf.updatePixels();

// ---- composite ----
noStroke();
drawingContext.imageSmoothingEnabled = !contour;
image(buf,0,0,W,Hh);
drawingContext.imageSmoothingEnabled = true;

const oldOp=drawingContext.globalCompositeOperation;

// nightvision: scanlines + travelling scan bar + phosphor grain
if(night){
  blendMode(MULTIPLY);
  stroke(0,0,0,55); strokeWeight(1);
  for(let y=0;y<Hh;y+=3) line(0,y,W,y);
  blendMode(SCREEN);
  const scanY=md(K.t*u*0.35,Hh);
  noStroke(); fill(120,60,100,14); rect(0,scanY-u*0.02,W,u*0.04);
  // grain
  fill(120,40,100,10); const gn=Math.floor(40+40*en);
  for(let i=0;i<gn;i++){const gx=frc(fr(i+Math.floor(K.t*12))*1.7)*W, gy=frc(fr(i+3+Math.floor(K.t*12))*1.3)*Hh; rect(gx,gy,2,2);}
  blendMode(BLEND);
}

// HUD reticle tracking the hottest blob (adds character + motion), skip for contour
if(!contour){
  let hot=bl[0]; for(const b of bl) if(b.str>hot.str) hot=b;
  const rx=hot.bx*W, ry=hot.by*Hh, rs=u*0.05*(1+0.15*K.pulse);
  stroke(night?140:50, night?70:10, night?100:98, 80); strokeWeight(1.4); noFill();
  rect(rx-rs,ry-rs,rs*2,rs*2);
  line(rx-rs*1.5,ry,rx-rs*0.6,ry); line(rx+rs*0.6,ry,rx+rs*1.5,ry);
  line(rx,ry-rs*1.5,rx,ry-rs*0.6); line(rx,ry+rs*0.6,rx,ry+rs*1.5);
  // corner brackets + blinking REC dot
  const m=u*0.04, cl=u*0.03;
  stroke(night?140:50,night?70:10,98,55); strokeWeight(1.2);
  [[m,m,1,1],[W-m,m,-1,1],[m,Hh-m,1,-1],[W-m,Hh-m,-1,-1]].forEach(c=>{line(c[0],c[1],c[0]+cl*c[2],c[1]);line(c[0],c[1],c[0],c[1]+cl*c[3]);});
  if(Math.sin(K.t*3)>0){ noStroke(); fill(2,90,95,90); circle(m+cl*1.4,m,u*0.012); }
  // scale-bar ticks along bottom (schematic ident, drifts)
  stroke(night?140:50,night?60:8,90,40); strokeWeight(1);
  const off=md(K.t*10,u*0.06);
  for(let x=-off;x<W;x+=u*0.06){ line(x,Hh-m,x,Hh-m-u*0.012); }
}

blendMode(BLEND); drawingContext.globalCompositeOperation=oldOp; drawingContext.shadowBlur=0; noStroke();
